import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.B_zcDAFh.js";const h=JSON.parse('{"title":"Boing Reactor Field","description":"","frontmatter":{},"headers":[],"relativePath":"guide/boing-reactor-field.md","filePath":"guide/boing-reactor-field.md"}'),i={name:"guide/boing-reactor-field.md"};function n(s,e,l,c,d,f){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="boing-reactor-field" tabindex="-1">Boing Reactor Field <a class="header-anchor" href="#boing-reactor-field" aria-label="Permalink to &quot;Boing Reactor Field&quot;">​</a></h1><p>The <strong>Boing Reactor Field</strong> component creates a &quot;proxy grid&quot; of reactors that effectors push, rather than pushing each affected object directly. It&#39;s an optimization for cases where many objects need to react to the same disturbance.</p><h2 id="trade-offs-vs-per-object-reactors" tabindex="-1">Trade-offs vs Per-Object Reactors <a class="header-anchor" href="#trade-offs-vs-per-object-reactors" aria-label="Permalink to &quot;Trade-offs vs Per-Object Reactors&quot;">​</a></h2><ul><li>The field only covers a limited volume defined by its grid dimensions and cell size.</li><li>In return, you can affect a large number of objects cheaply by sampling from the field — see <a href="./boing-reactor-field-sampler.html">Boing Reactor Field Sampler</a>.</li><li>The field can also be sampled directly from shaders (GPU), enabling effects on geometry that doesn&#39;t have its own component.</li></ul><h2 id="propagation" tabindex="-1">Propagation <a class="header-anchor" href="#propagation" aria-label="Permalink to &quot;Propagation&quot;">​</a></h2><p>A reactor field can be configured so disturbances <strong>propagate</strong> between neighboring cells rather than staying local to where an effector touched the grid. This produces wave-like effects: ripples, explosions radiating outward, wind blowing through a volume.</p><p>Propagation is an advanced mode. Before enabling it, make sure you&#39;re comfortable with the basics of how effectors and reactor fields interact in their non-propagating form — propagation depth interacts subtly with field dimensions, cell size, and decay parameters.</p><p>See the <a href="/boing-kit/gallery/field-propagation.html">Field Propagation gallery</a> for example scenes and the <a href="/boing-kit/api/boing-reactor-field.html">API reference</a> for the property list.</p>',8)])])}const g=a(i,[["render",n]]);export{h as __pageData,g as default};
